from pathlib import Path
import base64, zlib, re

payload=''''''

kt=Path('android-v0.1/app/src/main/java/ro/autoid/app/V100Screens.kt')
kt.write_bytes(zlib.decompress(base64.b64decode(payload)))

api=Path('android-v0.1/app/src/main/java/ro/autoid/app/data/AutoIdApi.kt')
s=api.read_text().replace('AutoID-Android/1.0.0','AutoID-Android/1.0.1')
api.write_text(s)

gradle=Path('android-v0.1/app/build.gradle.kts')
g=gradle.read_text().replace('versionName = "1.0.0"','versionName = "1.0.1"')
g=re.sub(r'versionCode\s*=\s*\d+', 'versionCode = 10100', g, count=1)
gradle.write_text(g)

print('Applied AutoID Android v1.0.1 catalog/product fixes')
